.contact {
  position: relative;
  padding: clamp(5rem, 10vw, 9rem) var(--gutter) 2rem;
  color: white;
  background: var(--forest-deep);
}
.contact > .contact__copy { width: min(50rem, 100%); }
.contact .section-title { color: var(--paper); }
.contact .eyebrow { color: rgba(255,255,255,.72); }
/* eyebrow on dark backgrounds (hero, film) — use warm off-white for legibility */
.hero .eyebrow,
.film .eyebrow { color: rgba(244,239,227,.82); }
.contact .body-copy { color: rgba(255,255,255,.68); }
.subscribe { width: min(45rem, 100%); margin: clamp(3rem, 7vw, 6rem) 0; }
.subscribe label {
  display: block;
  margin-bottom: .7rem;
  font-size: .6875rem;
  letter-spacing: .2em;
  font-family: var(--sans);
}
.subscribe__row { display: flex; border-bottom: 1px solid rgba(255,255,255,.45); }
.subscribe input {
  min-width: 0;
  flex: 1;
  padding: 1rem 0;
  color: white;
  border: 0;
  background: transparent;
  outline: none;
}
.subscribe input::placeholder { color: rgba(255,255,255,.38); }
.subscribe button {
  padding: .75rem 1rem;
  color: white;
  border: 0;
  background: transparent;
  cursor: pointer;
  letter-spacing: .14em;
  font-family: var(--sans);
  transition: color .2s;
}
.subscribe button:hover { color: var(--gold); }
.form-note {
  min-height: 1.5rem;
  margin: .8rem 0 0;
  color: rgba(255,255,255,.45);
  font-size: .6875rem;
  font-family: var(--sans);
}
.footer {
  display: flex;
  align-items: center;

